/**
 * 대한민국 행정구역 경계 — 화면용 SVG path (자동 생성물 · 직접 수정하지 말 것)
 *
 * 생성: node scripts/build-geo.mjs <provinces.json> <municipalities.json>
 * 출처: 통계청 2018 행정구역 경계(공공데이터) — southkorea-maps 공개 배포본
 * 투영: 웹 메르카토르 → viewBox 0 0 1000 1061 정규화
 *
 * 이 파일은 굽힌 결과라서 저장소에 커밋한다. 앱 실행에 네트워크가 필요 없다.
 */
export const GEO_VIEW = { w: 1000, h: 1061 } as const

/** 런타임 투영 상수 — 위 빌드와 반드시 같은 값이어야 마커가 경계 위에 정확히 얹힌다. */
const MERC = { minX: 2.174849853473097, maxY: 0.7316382242957999, scale: 9078.499198562626 } as const

/** 실측 경위도(WGS84) → 지도 viewBox 좌표. 빌드 스크립트의 project() 와 같은 식이다. */
export function projectLngLat(lng: number, lat: number): { x: number; y: number } {
  const mx = (lng * Math.PI) / 180
  const my = Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360))
  return {
    x: Math.round((mx - MERC.minX) * MERC.scale * 10) / 10,
    y: Math.round((MERC.maxY - my) * MERC.scale * 10) / 10,
  }
}

export interface GeoShape {
  /** 행정구역코드 — 시도 2자리, 시군구 5자리 */
  code: string
  name: string
  /** 시군구만: 소속 시도 코드(앞 2자리) */
  province?: string
  /** 대표점(무게중심) — 라벨·마커 위치 */
  cx: number
  cy: number
  /** SVG path d */
  d: string
}

